PROTOTYPES='void AudioPolice_SuspectReport(cAudioManager *manager);\n'
GAME_PROTOTYPES='CVehicle *AudioPoliceHost_FindVehicle(cAudioManager *manager);\nuint8_t AudioPoliceHost_VehicleColor(const CVehicle *vehicle);\nint16_t AudioPoliceHost_VehicleModel(const CVehicle *vehicle);\n'

def calls(source):
    # Replace only the former report bridge with its actual C operation
    return entries.calls(source.replace('AudioPoliceHost_SuspectReport(', 'AudioPolice_SuspectReport('))

def remove_bridge(source):
    # Remove the obsolete owner-delegating report adapter
    return source.replace(function(source,'AudioPoliceHost_','SuspectReport')+'\n','')

def radio(source):
    # Move the exact table and member into C and leave only vehicle access adapters
    source=source.replace(TABLE+'\n','').replace(function(source,'cAudioManager::','SetupSuspectLastSeenReport')+'\n','')
    return entries.radio(remove_bridge(source)+HOST)

def header(source):
    # Remove the obsolete member and bridge while preserving every owner field
    source='\n'.join(line for line in source.split('\n') if not re.search(r'\b(?:SetupSuspectLastSeenReport|AudioPoliceHost_SuspectReport)\(',line))
    return entries.header(source.replace('void AudioManager_InitState(cAudioManager *manager);',PROTOTYPES+'void AudioManager_InitState(cAudioManager *manager);'))

def game_header(source):
    # Declare the same opaque vehicle and three C field-access operations
    source=source.replace('class CPlayerPed;', 'class CPlayerPed;\nclass CVehicle;').replace('typedef struct CPlayerPed CPlayerPed;', 'typedef struct CPlayerPed CPlayerPed;\ntypedef struct CVehicle CVehicle;')
    source=source.replace('typedef struct AudioPoliceZoneView','typedef struct cAudioManager cAudioManager;\n'+'typedef struct AudioPoliceZoneView')
    return entries.game_header(source.replace('uint8_t AudioPoliceHost_MusicMode(void);',GAME_PROTOTYPES+'uint8_t AudioPoliceHost_MusicMode(void);'))

def body(source):
    # Preserve gate order, signed remainders, model selection and queue word order
    source=source[source.index('{'):]
    source=re.sub(r'(?<![.>\w])\b(m_\w+)\b',r'manager->\1',source)
    source=source.replace('uint8 ','uint8_t ').replace('uint32 ','uint32_t ').replace('nil','NULL')
    source=source.replace('MusicManager.m_nMusicMode', 'AudioPoliceHost_MusicMode()').replace('FindVehicleOfPlayer()', 'AudioPoliceHost_FindVehicle(manager)').replace('veh->m_currentColour1', 'AudioPoliceHost_VehicleColor(veh)').replace('veh->GetModelIndex()', 'AudioPoliceHost_VehicleModel(veh)').replace('debug(', 'AUDIO_POLICE_DEBUG(')
    return entries.suspect(source)
